mapper.select:
select ua.*,su.avatar as userAvatar,su.realname as userName,su.phone as userPhone from ums_sign ua left join sys_user su on su.id = ua.user_id where 1 = 1
and (su.realname like CONCAT('%',#{paramCondition.keyword},'%') or su.phone like CONCAT('%',#{paramCondition.keyword},'%'))
AND ua.user_id = #{paramCondition.userId}
AND ua.sign_type = #{paramCondition.signType}
order by ua.create_time desc
